// ANGSD doCounts and contamination estimation on the X-chromosome
//

include { ANGSD_DOCOUNTS      } from 'nf-core/angsd/docounts'
include { ANGSD_CONTAMINATION } from 'nf-core/angsd/contamination'

workflow BAM_DOCOUNTS_CONTAMINATION_ANGSD {

    take:
    ch_bam         // channel: [ val(meta), [ bam ], [ bai ] ]
    ch_hapmap_file // channel: [ val(meta), [ hapmap_file ] ]

    main:
    ANGSD_DOCOUNTS ( ch_bam.combine(channel.of([[]])) )

    ANGSD_CONTAMINATION (
        ANGSD_DOCOUNTS.out.icounts,
        ch_hapmap_file
    )

    emit:
    txt      = ANGSD_CONTAMINATION.out.txt // channel: [ val(meta), [ txt ] ]
}

nextflow_workflow {

    name "Test Workflow BAM_DOCOUNTS_CONTAMINATION_ANGSD"
    config "./nextflow.config"
    script "../main.nf"

    workflow "BAM_DOCOUNTS_CONTAMINATION_ANGSD"
    tag "subworkflows"
    tag "subworkflows_nfcore"
    tag "subworkflows/bam_docounts_contamination_angsd"
    tag "bam_docounts_contamination_angsd"
    tag "angsd/docounts"
    tag "angsd/contamination"
    tag "angsd"

    test("homo_sapiens - bam bai - hapmap") {
        when {
            params {
                angsd_docounts_args = "-iCounts 1"
            }
            workflow {
                """
                input[0] = Channel.of([
                    [id:'test'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test.paired_end.markduplicates.sorted.bam', checkIfExists:true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test.paired_end.markduplicates.sorted.bam.bai', checkIfExists:true)
                ])
                input[1] = Channel.of([
                    [id:'hapmap'],
                    file("https://github.com/nf-core/test-datasets/raw/modules/data/delete_me/angsd/HapMapChrX.gz", checkIfExists:true)
                ])
                """
            }
        }
        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(sanitizeOutput(workflow.out)).match() }
            )
        }
    }

    test("homo_sapiens - bam bai - hapmap -- stub") {
        options "-stub"
        when {
            params {
                angsd_docounts_args = "-iCounts 1"
            }
            workflow {
                """
                input[0] = Channel.of([
                    [id:'test'],
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test.paired_end.markduplicates.sorted.bam', checkIfExists:true),
                    file(params.modules_testdata_base_path + 'genomics/homo_sapiens/illumina/bam/test.paired_end.markduplicates.sorted.bam.bai', checkIfExists:true)
                ])
                input[1] = Channel.of([
                    [id:'hapmap'],
                    file("https://github.com/nf-core/test-datasets/raw/modules/data/delete_me/angsd/HapMapChrX.gz", checkIfExists:true)
                ])
                """
            }
        }
        then {
            assertAll(
                { assert workflow.success },
                { assert snapshot(sanitizeOutput(workflow.out)).match() }
            )
        }
    }
}

